def connect_sources(source,core,mobile):
 prep=module("connect_mtu_projection",source/"deploy/prepare-mobile-connect.py")
 expected={relative for name,relative in prep.TEMPLATES.items() if (not mobile or name not in prep.DESKTOP_ONLY) and (mobile or not relative.startswith("experimental/libbox/"))}
 record=json.loads((core/prep.OWNER).read_bytes())
 if set(record["files"])!=expected:raise ValueError("CONNECT MTU native source inventory changed")
 for name,relative in prep.TEMPLATES.items():
  if relative not in expected:continue
  a,b=source/"mobile/chain"/name,core/relative
  if a.is_symlink() or b.is_symlink() or a.read_bytes()!=b.read_bytes() or hashlib.sha256(b.read_bytes()).hexdigest()!=record["files"][relative]:
   raise ValueError("CONNECT MTU original projection changed: "+relative)
 if prep.box_source((core/"box.go").read_text())!=(core/"box.go").read_text():raise ValueError("CONNECT MTU acquired Box binding changed")
 if "routervpnnodeconnect" in (core/"include/registry.go").read_text():raise ValueError("CONNECT MTU acquired global factory")

def checked_sources(source,core,xray):
 result=_original_checked(source,core,xray);connect_sources(source,core,True);return result

def checked_owner_sources(source,core,xray):
 result=_original_owner_checked(source,core,xray);connect_sources(source,core,False);return result
BASE.checked_sources=checked_sources
BASE.checked_owner_sources=checked_owner_sources

def validate(source,source_sha,output,go="go"):
 receipt=BASE.validate(source,source_sha,output,go)
 receipt.update(scope="original SOCKS native MTU gates plus distinct CONNECT native MTU component ownership",
  preserved_typed_cases=list(PRESERVED_TYPED),preserved_box_cases=list(PRESERVED_BOX),
  native_connect_mtu_cases=list(NATIVE_CASES),libbox_connect_mtu_cases=list(WRAPPER_CASES),
  native_connect_mtu_component_accepted=True,encrypted_connect_run_accepted=False,
  public_mtu_constructor_accepted=False,generated_sdk_accepted=False,physical_mtu_accepted=False,
  mtu_component_boundaries=["OS TUN acquisition and interface observation","packet/proof component boundary"],
  trusted_extended_validator_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest())
 for name in ("receipt.json","progress.json"):
  path=Path(output)/name;temporary=path.with_suffix(".tmp");temporary.write_text(json.dumps(receipt,indent=2)+"\n");temporary.replace(path)
 return receipt

def main():
 parser=argparse.ArgumentParser(description=__doc__)
 parser.add_argument("--suite",required=True,choices=(SUITE,));parser.add_argument("--source",required=True,type=Path)
 parser.add_argument("--source-sha",required=True);parser.add_argument("--output",required=True,type=Path);parser.add_argument("--go",default="go")
 args=parser.parse_args();validate(args.source,args.source_sha,args.output,args.go)
if __name__=="__main__":main()
